// AI generated by GitHub Copilot (DeepSeek V4 Pro), v2.0
class CountingSink : public ImportSink
{
public:
    std::size_t rows = 0;

    bool store( const std::vector<DataRecord> & batch ) override
    {
        rows += batch.size();
        return true;
    }
};
