void print_result( ColoredOutput & co, const std::string & file,
                   const std::string & db_newest,
                   std::streamoff start_offset, const ImportResult & res,
                   const std::string & error )
{
    std::cout << "file      : " << file << '\n'
              << "db newest : " << ( db_newest.empty() ? std::string( "(empty)" ) : db_newest ) << '\n'
              << "offset    : " << (long long)start_offset
              << " -> " << (long long)res.end_offset << '\n'
              << "lines     : " << res.lines << '\n'
              << "days      : " << res.days << '\n'
              << "records   : " << res.records << '\n'
              << "skipped   : " << res.duplicates << " (already in the database)\n"
              << "empty     : " << res.empty << '\n'
              << "malformed : " << res.malformed << '\n';

    if( !error.empty() ) {
        std::cout << "error     : "
                  << co.color_output( ColoredOutput::BRIGHT_RED, error ) << '\n';
    }

    std::cout << "result    : "
              << co.color_output( res.ok ? ColoredOutput::GREEN : ColoredOutput::RED,
                                  res.ok ? "ok" : "failed" )
              << std::endl;
}
// End of AI generated by GitHub Copilot (DeepSeek V4 Pro), v2.0

// AI generated by GitHub Copilot (DeepSeek V4 Pro), v2.0
/** 0 = ok, 4 = import failed, 6 = file changed while reading */
int exit_code( const std::string & csv, const ImportResult & res )
{
    if( res.file_changed ) {
        std::cerr << csv << ": the file was modified while reading (rsync?), "
                  << "the import is aborted - the next run continues" << std::endl;
        return 6;
    }

    return res.ok ? 0 : 4;
}
